(function(){
 'use strict';
 const C=window.WorkAnalysis,$=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const state={result:C.createDemo(),mode:'zero',view:'workspace',selected:'seg_001',time:0,video:null,url:null,reference:null,dirty:false,page:0,loading:false};
 const PAGE=100,palette=['#368c95','#547e9d','#537984','#477d94','#7883aa','#388982','#698e9c','#698079','#517985','#387b88'];
 let toastTimer,videoToken=0;
 function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,4500)}
 function segs(){return state.result?.modes[state.mode]?.segments||[]}
 function selected(){return segs().find(s=>s.id===state.selected)||segs()[0]}
 function badge(s){return `<span class="badge ${s.match_status}">${esc(C.matchNames[s.match_status])}</span>`}
 function reviewBadge(s){return `<span class="badge ${s.review_status==='verified'?'verified':''}">${esc(C.reviewNames[s.review_status])}</span>`}
 function standardName(s){return state.result?.standard_cards.find(c=>c.id===s.standard_id)?.name||'対応未確定'}
 function discard(){return !state.dirty||window.confirm('未保存の修正があります。結果を保存せずに入れ替えますか？')}
 function emptyText(){return state.result?'この方式の結果はまだありません。':'この動画は未分析です。操作用サンプル、または結果JSONを表示してください。'}
 function setView(view){if(!['workspace','compare','analytics','sop'].includes(view))throw Error('画面が見つかりません。');state.view=view;document.querySelectorAll('.view').forEach(x=>x.hidden=x.id!==view);document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===view));$('viewTitle').textContent={workspace:'動画と作業区間',compare:'標準との比較',analytics:'時間の分析',sop:'実施手順書'}[view];if(view==='compare')renderCompare();if(view==='analytics')renderAnalytics();if(view==='sop')renderSop();}
 function setMode(mode){if(!['zero','few'].includes(mode))throw Error('分析方式が不正です。');state.mode=mode;state.page=0;if(!segs().some(s=>s.id===state.selected))state.selected=segs()[0]?.id;render();}
 function resultNotice(){
  const n=$('dataNotice');n.classList.toggle('real',state.result&&state.result.data_source!=='demo');
  n.textContent=!state.result?'この動画は未分析です。「操作用サンプルを表示」で画面を試すか、実際の結果JSONを読み込んでください。':state.result.data_source==='demo'?'操作用サンプルを表示中です。区間・作業名・数値は架空で、読み込んだ映像の内容を解析していません。':'読み込んだ結果JSONを表示中です。この画面ではAIを実行していません。結果の作業・境界を動画で確認してください。';
 }
 function render(){
  resultNotice();$('dirtyTag').hidden=!state.dirty;$('sampleButton').disabled=state.loading;$('importButton').disabled=state.loading;
  document.querySelectorAll('[data-mode]').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.mode===state.mode)));
  $('modeDescription').textContent=state.mode==='zero'?'動画の観察と標準書から、作業の候補を確認します。':'正解付きの見本を参照する方式の結果を確認します。';
  $('fileName').textContent=state.video?.name||state.result?.video.name||'対象動画を選んでください';
  $('fileMeta').textContent=state.video?`${C.pretty(state.video.duration_sec)} / ${Math.round(state.video.size_bytes/1024/1024)} MB / このブラウザで再生`:'動画未選択 / '+(state.result?`結果のみ表示・${C.pretty(state.result.video.duration_sec)}`:'動画を選択してください');
  $('exportButton').disabled=!state.result;$('csvButton').disabled=!segs().length;
  const len=state.video?.duration_sec||state.result?.video.duration_sec||0;$('seek').max=len;$('seek').disabled=!len;$('totalClock').textContent=C.mmss(len);
  $('playerSource').textContent=state.video?'ローカル動画':state.result?'結果の時間軸（動画未選択）':'動画未選択';
  renderMetrics();renderTimeline();renderList();renderInspector();setView(state.view);syncTime(state.time,false);
 }
 function renderMetrics(){const r=state.result,st=r?C.stats(r,state.mode):null;const present=!!segs().length;let items=[['サイクル時間',r?C.pretty(r.video.duration_sec):state.video?C.pretty(state.video.duration_sec):'—','比較基準 '+C.pretty(r?.tt_sec||4800)],['観察した作業',present?st.count:'—','件','標準書の工程数とは異なります'],['未記載の時間',present?C.pretty(st.totals.unmatched):'—','標準書にない活動も残します'],['人の確認が必要',present?st.pending:'—','件',present?`${st.reviewed} / ${st.count}件を確認済み`:'結果を読み込んでください']];$('metrics').innerHTML=items.map((x,i)=>`<div class="metric ${i===3?'attention':''}"><div class="metric-label">${x[0]}</div><div class="metric-value">${esc(x[1])}${x.length===4?'<small>'+x[2]+'</small>':''}</div><div class="metric-note">${esc(x.at(-1))}</div></div>`).join('')}
 function renderTimeline(){const all=segs(),len=state.result?.video.duration_sec||1;$('timeline').innerHTML=all.map(s=>`<button class="${s.match_status}" style="width:${C.duration(s)/len*100}%" data-segment="${esc(s.id)}" title="${esc(C.mmss(s.start_sec)+' '+s.action)}" aria-label="${esc(s.action+' '+C.mmss(s.start_sec)+'から')}" ></button>`).join('')}
 function filtered(){let q=$('search').value.trim().toLowerCase(),f=$('filter').value;return segs().filter(s=>(f==='all'||f==='pending'&&s.review_status!=='verified'||s.match_status===f)&&(!q||[s.action,s.object,s.location,s.tool].some(v=>v.toLowerCase().includes(q))))}
 function renderList(){
  const all=filtered(),pages=Math.max(1,Math.ceil(all.length/PAGE));state.page=Math.min(state.page,pages-1);$('listCount').textContent=`${all.length} / ${segs().length}件`;
  $('segmentList').innerHTML=all.length?all.slice(state.page*PAGE,(state.page+1)*PAGE).map(s=>`<button class="segment-row" data-segment="${esc(s.id)}" aria-current="${s.id===state.selected}"><span class="row-index">${String(segs().indexOf(s)+1).padStart(2,'0')}</span><span class="row-main"><span class="row-top"><span>${C.mmss(s.start_sec)} — ${C.mmss(s.end_sec)}</span><span>${C.pretty(C.duration(s))}</span></span><span class="row-name">${esc(s.action)}</span><span class="row-bottom">${badge(s)}${reviewBadge(s)}<span>${esc(C.activityNames[s.activity])}</span></span></span></button>`).join(''):`<div class="empty-state"><h3>${segs().length?'該当する作業はありません':'結果を表示してください'}</h3><p>${esc(segs().length?'検索・絞り込みを変更してください。':emptyText())}</p></div>`;
  $('prevPage').disabled=state.page===0;$('nextPage').disabled=state.page>=pages-1;$('pageInfo').textContent=`${state.page+1} / ${pages}`;
 }
 function renderInspector(){const s=selected();if(!s){$('inspector').innerHTML=`<div class="empty-state">${esc(emptyText())}</div>`;return}
  $('inspector').innerHTML=`<div class="inspector-top"><span class="segment-number">選択中の作業 ${String(segs().indexOf(s)+1).padStart(2,'0')}</span><div class="badges">${badge(s)}${reviewBadge(s)}</div></div><h3>${esc(s.action)}</h3><div class="time-meta">${C.mmss(s.start_sec)} — ${C.mmss(s.end_sec)}　/　${C.pretty(C.duration(s))}</div><dl class="facts"><div class="fact"><dt>対象物</dt><dd>${esc(s.object||'不明')}</dd></div><div class="fact"><dt>場所</dt><dd>${esc(s.location||'不明')}</dd></div><div class="fact"><dt>工具・道具</dt><dd>${esc(s.tool||'不明')}</dd></div><div class="fact"><dt>標準との対応</dt><dd>${esc(s.standard_id||'—')} ${esc(standardName(s))}</dd></div></dl><div class="state-change"><div><span>作業の前</span><p>${esc(s.before||'未記録')}</p></div><div><span>作業の後</span><p>${esc(s.after||'未記録')}</p></div></div><p class="evidence">${esc(s.evidence||'証拠の記録なし')}</p>${s.note?'<p class="evidence">確認メモ：'+esc(s.note)+'</p>':''}<div class="row-bottom"><span>方法：${{conforming:'指定通り',deviating:'相違あり',unknown:'未判定',not_applicable:'対象外'}[s.method_status]}</span><span>順序：${{allowed:'許容',violation_candidate:'逸脱候補',unknown:'未判定'}[s.order_status]}</span></div><div class="inspector-actions"><button class="button primary" id="verifySelected" ${s.review_status==='verified'?'disabled':''}>確認済みにする</button><button class="button secondary" id="editSelected">区間・対応を修正</button><button class="button secondary" data-segment="${esc(s.id)}">始まりへ移動</button></div>`;
 }
 function syncTime(t,follow=true){let len=state.video?.duration_sec||state.result?.video.duration_sec||0;state.time=Math.max(0,Math.min(Number(t)||0,len));$('clock').textContent=C.mmss(state.time);$('seek').value=state.time;if(!follow)return;let s=segs().find(x=>x.start_sec<=state.time&&x.end_sec>state.time)||segs().at(-1);if(s&&s.id!==state.selected){state.selected=s.id;document.querySelectorAll('.segment-row').forEach(r=>r.setAttribute('aria-current',String(r.dataset.segment===s.id)));renderInspector();}}
 function choose(id,go=true){let s=segs().find(x=>x.id===id);if(!s)throw Error('区間が見つかりません。');state.selected=id;syncTime(s.start_sec,false);if(state.video&&go){try{$('player').currentTime=s.start_sec}catch(_){}}renderList();renderInspector();}
 function jump(id){setView('workspace');choose(id);$('workspace').scrollIntoView({behavior:'smooth',block:'start'})}
 function emptyView(){return `<div class="panel empty-state"><h3>分析結果はまだありません</h3><p>${esc(emptyText())}</p></div>`}
 function renderCompare(){if(!segs().length){$('compare').innerHTML=emptyView();return}const r=state.result,st=C.stats(r,state.mode);$('compare').innerHTML=`<div class="section-intro"><div><h2>標準と実作業の違い</h2><p>実行順を保ったまま対応づけます。未観察は実施漏れと同じ意味ではありません。</p></div></div><div class="comparison-cards">${['zero','few'].map(m=>{let v=C.stats(r,m);return `<div class="comparison-card ${m===state.mode?'active':''}"><h3>${m==='zero'?'見本なし / Zero-shot':'見本あり / Few-shot'}</h3>${r.modes[m]?`<div class="comparison-nums"><div><span>${C.pretty(v.totals.matched)}</span><small>標準作業に対応</small></div><div><span>${C.pretty(v.totals.uncertain)}</span><small>対応を要確認</small></div><div><span>${v.pending}件</span><small>人の確認が必要</small></div></div>`:'<p>この方式の結果はありません。</p>'}</div>`}).join('')}</div><div class="analysis-note">この比較は結果の分類内訳です。どちらが正しいかは、別に作成した正解データで評価します。</div><div class="panel"><div class="panel-heading"><h2>標準作業ごとの対応</h2><span>選択中の方式</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>標準作業</th><th>記載の時間</th><th>観察された時間</th><th>対応区間</th><th>確認</th></tr></thead><tbody>${st.groups.map(g=>`<tr><td><small>${esc(g.id)}</small><br>${esc(g.name)}</td><td>${g.duration_sec==null?'未設定':C.pretty(g.duration_sec)}</td><td>${g.segments.length?C.pretty(g.actual):'未観察'}</td><td>${g.segments.map(s=>`<button class="clickable" data-jump="${esc(s.id)}">${C.mmss(s.start_sec)} ${esc(s.action)}</button>`).join('<br>')||'撮影範囲・条件を確認'}</td><td>${g.segments.length?g.segments.every(s=>s.review_status==='verified')?'確認済み':'未確認を含む':'要確認'}</td></tr>`).join('')}</tbody></table></div></div><div class="section-intro" style="margin-top:28px"><div><h2>標準書にない活動</h2><p>必要な付随作業か、改善できる動きかを現場で確認します。</p></div></div><div class="outside-list">${segs().filter(s=>s.match_status==='unmatched').map(s=>`<button class="outside-card" data-jump="${esc(s.id)}">${esc(s.action)}<span>${C.pretty(C.duration(s))}</span></button>`).join('')||'<p>未記載として分類された区間はありません。</p>'}</div>`}
 function renderAnalytics(){if(!segs().length){$('analytics').innerHTML=emptyView();return}const r=state.result,st=C.stats(r,state.mode),len=r.video.duration_sec,max=Math.max(len,r.tt_sec)*1.08;let groups=st.groups.filter(g=>g.actual>0).map((g,i)=>({name:g.name,seconds:g.actual,color:palette[i%palette.length],segment:g.segments[0].id}));['unmatched','uncertain'].forEach(m=>{let a=segs().filter(s=>s.match_status===m);if(a.length)groups.push({name:C.matchNames[m],seconds:a.reduce((v,s)=>v+C.duration(s),0),color:m==='unmatched'?'#d29b3b':'#9aa6af',segment:a[0].id})});
  $('analytics').innerHTML=`<div class="section-intro"><div><h2>時間の内訳を確認する</h2><p>一人の作業時間を3つの見方で表示します。区間を押すと元の動画へ戻れます。</p></div></div><div class="analysis-note">集計は主タイムラインに基づきます。標準ID別の集計には「一部対応」を含みます。未記載・判定不能も総時間から除外しません。</div><div class="charts"><section class="panel chart-panel"><h2>山積み表 <small>作業負荷の内訳</small></h2><p>同じ作業の時間をまとめ、比較基準80分と比べます。全ラインの負荷ではなく、この一人分の時間内訳です。</p><div class="stack-chart"><div class="tt-marker" style="left:${r.tt_sec/max*100}%"><span>基準 ${C.pretty(r.tt_sec)}</span></div><div class="stack-row">${groups.map(g=>`<button data-jump="${esc(g.segment)}" style="width:${g.seconds/max*100}%;background:${g.color}" title="${esc(g.name)} ${C.pretty(g.seconds)}" aria-label="${esc(g.name)} ${C.pretty(g.seconds)}"></button>`).join('')}</div></div><div class="axis"><span>0分</span><span>${C.pretty(len)}（実測） / 軸上限 ${Math.round(max/60)}分</span></div><div class="chart-key">${groups.map(g=>`<span><i style="background:${g.color}"></i>${esc(g.name)} ${C.pretty(g.seconds)}</span>`).join('')}</div></section><section class="panel chart-panel"><h2>ガントチャート <small>いつ・どの順で実施したか</small></h2><p>横軸は元動画の時間です。中断や繰り返しをそのまま残します。</p><div class="axis"><span>作業 / 0分</span><span>${C.pretty(len)}</span></div>${segs().slice(0,200).map(s=>`<div class="gantt-row"><div class="gantt-label">${esc(s.action)}</div><div class="gantt-track"><button class="${s.match_status}" data-jump="${esc(s.id)}" style="left:${s.start_sec/len*100}%;width:${C.duration(s)/len*100}%" aria-label="${esc(s.action)} ${C.mmss(s.start_sec)}から" title="${C.mmss(s.start_sec)} — ${C.mmss(s.end_sec)}"></button></div><span>${C.pretty(C.duration(s))}</span></div>`).join('')}${segs().length>200?'<p>表示は先頭200区間です。全区間はCSVで確認できます。</p>':''}</section><section class="panel chart-panel"><h2>バレットグラフ <small>標準時間と実績の差</small></h2><p>青緑の棒は観察時間、黒い線は標準書の時間。同じ工程でも製品や数量が違う場合は条件を確認します。</p>${st.groups.map(g=>{let m=Math.max(g.actual,g.duration_sec||0,1)*1.3;return `<div class="bullet-row"><div>${esc(g.name)}</div><div class="bullet-track"><div class="bullet-actual" style="width:${g.actual/m*100}%"></div>${g.duration_sec!=null?`<div class="bullet-target" style="left:${g.duration_sec/m*100}%" title="標準 ${C.pretty(g.duration_sec)}"></div>`:''}</div><div class="bullet-number">${C.pretty(g.actual)} / ${g.duration_sec==null?'標準未設定':C.pretty(g.duration_sec)}<br><small>${!g.segments.length?'未観察':g.duration_sec>0?Math.round(g.actual/g.duration_sec*100)+'%':'比率なし'}</small></div></div>`}).join('')}</section></div>`;
 }
 function renderSop(){if(!segs().length){$('sop').innerHTML=emptyView();return}$('sop').innerHTML=`<div class="section-intro"><div><h2>行動者ベースの実施手順書</h2><p>実際に観察した行動を記録します。正式に承認された標準書とは別に扱います。</p></div></div><div class="sop-context">観察記録（As-is案） / 対象 ${esc(state.result.video.name)}<br>見えない作業の理由・品質・安全条件は補いません。サンプル表示時は、この手順書も架空の内容です。</div><div class="panel table-wrap"><table class="data-table sop-table"><thead><tr><th>順番・時間</th><th>観察した行動</th><th>対象・工具・場所</th><th>開始・終了状態</th><th>根拠と未確認事項</th></tr></thead><tbody>${segs().slice(0,200).map((s,i)=>`<tr><td>${String(i+1).padStart(2,'0')}<br><button class="clickable" data-jump="${esc(s.id)}">${C.mmss(s.start_sec)} — ${C.mmss(s.end_sec)}</button><br><small>${C.pretty(C.duration(s))}</small></td><td>${esc(s.action)}<br>${badge(s)} ${reviewBadge(s)}</td><td>${esc(s.object)}<br>${esc(s.tool)}<br><small>${esc(s.location)}</small></td><td class="state-cell"><span>前</span>${esc(s.before)}<span>後</span>${esc(s.after)}</td><td>${esc(s.evidence)}${s.note?'<br>メモ：'+esc(s.note):''}</td></tr>`).join('')}</tbody></table></div>${segs().length>200?'<p class="analysis-note">画面は先頭200区間です。全区間はJSON・CSVで保存できます。</p>':''}`}
 function markVerified(){const s=selected();if(!s)return;state.result=C.update(state.result,state.mode,s.id,{...s,review_status:'verified'});state.dirty=true;render();toast('確認済みにしました。結果を保存すると修正を残せます。')}
 function openEdit(){let s=selected();if(!s)return;const f=$('editForm');$('editAction').textContent=s.action;f.elements.start_sec.value=s.start_sec;f.elements.end_sec.value=s.end_sec;f.elements.start_sec.disabled=segs()[0].id===s.id;f.elements.end_sec.disabled=segs().at(-1).id===s.id;f.elements.standard_id.innerHTML='<option value="">対応なし</option>'+state.result.standard_cards.map(c=>`<option value="${esc(c.id)}">${esc(c.id)} ${esc(c.name)}</option>`).join('');['standard_id','match_status','review_status','note'].forEach(k=>f.elements[k].value=s[k]||'');adjustMatch();$('editError').hidden=true;$('editDialog').showModal()}
 function adjustMatch(){const f=$('editForm');const assign=['matched','partial'].includes(f.elements.match_status.value);f.elements.standard_id.disabled=!assign;if(!assign)f.elements.standard_id.value='';}
 $('editForm').elements.match_status.addEventListener('change',adjustMatch);
 $('editForm').addEventListener('submit',e=>{e.preventDefault();const f=e.currentTarget,s=selected();try{const patch={start_sec:Number(f.elements.start_sec.value),end_sec:Number(f.elements.end_sec.value),match_status:f.elements.match_status.value,standard_id:f.elements.standard_id.value||null,review_status:f.elements.review_status.value,note:f.elements.note.value};state.result=C.update(state.result,state.mode,s.id,patch);state.dirty=true;$('editDialog').close();render();toast('修正を反映しました。必要な区間を再確認してください。')}catch(err){$('editError').textContent=err.message;$('editError').hidden=false}});
 async function loadVideo(file){if(!file)return;if(!discard())return;if(!file.type.startsWith('video/')&&!/\.(mp4|webm|mov|m4v|ogv)$/i.test(file.name)){toast('動画ファイルを選んでください。');return}const token=++videoToken;const player=$('player');player.pause();if(state.url)URL.revokeObjectURL(state.url);state.url=URL.createObjectURL(file);state.result=null;state.selected=null;state.time=0;state.video=null;state.loading=true;state.dirty=false;player.hidden=false;$('videoEmpty').hidden=true;render();$('fileName').textContent=file.name;$('fileMeta').textContent='動画を読み込んでいます…';
  player.onloadedmetadata=()=>{if(token!==videoToken)return;if(!Number.isFinite(player.duration)||player.duration<=0){failVideo();return}state.video={name:file.name,size_bytes:file.size,duration_sec:player.duration};state.loading=false;render();if(player.duration>7200)toast('120分を超えています。実分析では処理条件の確認が必要です。')};
  player.onerror=()=>{if(token===videoToken)failVideo()};player.src=state.url;player.load();
 }
 function failVideo(){++videoToken;$('player').pause();$('player').removeAttribute('src');$('player').hidden=true;$('videoEmpty').hidden=false;if(state.url)URL.revokeObjectURL(state.url);state.url=null;state.video=null;state.loading=false;render();toast('動画を再生できません。MP4など対応形式やファイルの破損を確認してください。')}
 function showSample(){if(!discard())return;state.result=C.createDemo(state.video?.duration_sec||7200,state.video?.name||'工程A・サンプル動画',state.video?.size_bytes||null);state.selected='seg_001';state.time=0;state.dirty=false;state.page=0;$('search').value='';$('filter').value='all';render();toast('操作用の架空データを表示しました。映像の内容は解析していません。')}
 async function importResult(file){if(!file||!discard())return;if(file.size>10*1024*1024){toast('結果JSONは10MB以下にしてください。');return}try{let next=C.validate(JSON.parse(await file.text()));if(state.video){const v=state.video;if(next.video.name!==v.name||next.video.size_bytes!=null&&next.video.size_bytes!==v.size_bytes||Math.abs(next.video.duration_sec-v.duration_sec)>2)throw Error('選択した動画と結果の動画名・容量・時間が一致しません。対応する結果を読み込んでください。');for(const m of ['zero','few'])if(next.modes[m])next.modes[m].segments.at(-1).end_sec=v.duration_sec;next.video={...v};next=C.validate(next)}state.result=next;if(!next.modes[state.mode])state.mode=next.modes.zero?'zero':'few';state.selected=next.modes[state.mode].segments[0].id;state.time=0;state.dirty=false;state.page=0;$('search').value='';$('filter').value='all';render();toast('結果を読み込みました。動画を見ながら確認してください。')}catch(err){toast('読み込めませんでした：'+err.message)}}
 function download(text,type,name){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1500)}
 function save(){if(!state.result)return;download(JSON.stringify(state.result,null,2),'application/json',`genba-results-${state.result.data_source}.json`);state.dirty=false;$('dirtyTag').hidden=true;toast('JSONの保存を開始しました。ブラウザのダウンロード先を確認してください。')}
 document.addEventListener('click',e=>{let x=e.target.closest('[data-view]');if(x){setView(x.dataset.view);return}x=e.target.closest('[data-mode]');if(x){setMode(x.dataset.mode);return}x=e.target.closest('[data-segment]');if(x){choose(x.dataset.segment);return}x=e.target.closest('[data-jump]');if(x){jump(x.dataset.jump);return}x=e.target.closest('[data-close]');if(x){$(x.dataset.close).close();return}if(e.target.closest('#verifySelected'))markVerified();if(e.target.closest('#editSelected'))openEdit()});
 $('videoButton').onclick=$('videoEmptyButton').onclick=()=>$('videoInput').click();$('videoInput').onchange=e=>{loadVideo(e.target.files[0]);e.target.value=''};
 $('referenceButton').onclick=()=>$('referenceInput').click();$('referenceInput').onchange=e=>{let f=e.target.files[0];if(f){state.reference={name:f.name,size:f.size};$('referenceInfo').hidden=false;$('referenceInfo').textContent='見本：'+f.name+' / 登録操作の確認のみ。正解ラベルの照合・Gemini分析にはまだ接続していません。';toast('見本動画の選択を確認しました。モックの結果は架空データです。')}e.target.value=''};
 $('importButton').onclick=()=>$('resultInput').click();$('resultInput').onchange=e=>{importResult(e.target.files[0]);e.target.value=''};
 $('sampleButton').onclick=showSample;$('exportButton').onclick=save;$('csvButton').onclick=()=>{if(state.result)download(C.csv(state.result,state.mode),'text/csv;charset=utf-8',`genba-segments-${state.mode}-${state.result.data_source}.csv`)};
 $('helpButton').onclick=()=>$('helpDialog').showModal();$('search').oninput=$('filter').onchange=()=>{state.page=0;renderList()};$('prevPage').onclick=()=>{state.page--;renderList()};$('nextPage').onclick=()=>{state.page++;renderList()};
 $('player').addEventListener('timeupdate',()=>syncTime($('player').currentTime));$('seek').oninput=e=>{let t=Number(e.target.value);if(state.video)$('player').currentTime=t;syncTime(t)};
 window.addEventListener('beforeunload',e=>{if(state.dirty){e.preventDefault();e.returnValue=''}});window.addEventListener('pagehide',e=>{if(!e.persisted&&state.url)URL.revokeObjectURL(state.url)});
 // Progressive enhancement: the same read/navigation actions are available to a supported browser agent.
 const context=document.modelContext,lifecycle=new AbortController();
 if(context?.registerTool){for(const tool of [
  {name:'read_work_analysis',title:'現在の分析結果を読む',description:'Return the visible mode, data source and computed totals without changing the result.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({mode:state.mode,data_source:state.result?.data_source||null,summary:state.result?C.stats(state.result,state.mode):null})},
  {name:'navigate_analysis_mode',title:'分析方式を切り替える',description:'Switch the visible result between zero and few. Does not run an analysis.',inputSchema:{type:'object',properties:{mode:{type:'string',enum:['zero','few']}},required:['mode'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||!['zero','few'].includes(input.mode)||Object.keys(input).some(k=>k!=='mode'))throw Error('mode must be zero or few');setMode(input.mode);return {mode:state.mode,available:!!state.result?.modes[state.mode]}}}
 ]){try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch(_){}}window.addEventListener('pagehide',()=>lifecycle.abort())}
 render();
})();
